using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);

// Register ProblemDetails services — this enables RFC 7807 responses
builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = context =>
    {
        // Always include the trace identifier for correlation
        context.ProblemDetails.Extensions["traceId"] =
            context.HttpContext.TraceIdentifier;
    };
});

builder.Services.AddOpenApi();

var app = builder.Build();

// Global exception handler — maps known exceptions to proper status codes
app.UseExceptionHandler(exceptionApp =>
{
    exceptionApp.Run(async context =>
    {
        var exceptionFeature = context.Features.Get<IExceptionHandlerFeature>();
        var exception = exceptionFeature?.Error;

        var (statusCode, title) = exception switch
        {
            KeyNotFoundException   => (StatusCodes.Status404NotFound,    "Resource not found"),
            ArgumentException      => (StatusCodes.Status400BadRequest,  "Invalid request"),
            InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
            _ => (StatusCodes.Status500InternalServerError, "An unexpected error occurred")
        };

        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title  = title,
            // Only include exception details in non-500 responses
            Detail = statusCode != StatusCodes.Status500InternalServerError
                ? exception?.Message
                : null
        };

        context.Response.StatusCode = statusCode;
        await context.Response.WriteAsJsonAsync(problemDetails);
    });
});

// Also return ProblemDetails for empty error responses (e.g. 404 from routing)
app.UseStatusCodePages();

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
}

// --- Demo endpoints ---

var items = new Dictionary<string, string>
{
    ["1"] = "First item",
    ["2"] = "Second item"
};

app.MapGet("/items/{id}", (string id) =>
{
    if (!items.TryGetValue(id, out var value))
        throw new KeyNotFoundException($"Item '{id}' was not found.");
    return Results.Ok(new { id, value });
});

app.MapPost("/items/{id}", (string id, string value) =>
{
    if (string.IsNullOrWhiteSpace(value))
        throw new ArgumentException("Value must not be empty.");
    if (items.ContainsKey(id))
        throw new InvalidOperationException($"Item '{id}' already exists.");
    items[id] = value;
    return Results.Created($"/items/{id}", new { id, value });
});

app.MapGet("/error", () =>
{
    throw new Exception("Something broke!");
});

app.Run();

